@push('scripts')<script>
document.getElementById('ev_holiday')?.addEventListener('change', function(){ document.getElementById('ev_type_wrap').classList.toggle('hidden', this.checked); });
document.getElementById('ev_audition')?.addEventListener('change', function(){
 const v=this.value; const wrap=document.getElementById('ev_audience_wrap'); const sel=document.getElementById('ev_audience');
 if(v==1){ wrap.classList.add('hidden'); sel.innerHTML=''; }
 else if(v==2){ wrap.classList.remove('hidden'); fetch('{{ route('ajax.getClassByBranch') }}', {method:'POST', headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Content-Type':'application/json'}, body: JSON.stringify({branch_id: document.getElementById('ev_branch')?.value || '{{ $branch_id }}'})}).then(r=>r.text()).then(html=>{ sel.innerHTML=html; }); }
 else if(v==3){ wrap.classList.remove('hidden'); fetch('{{ route('events.getSectionByBranch') }}', {method:'POST', headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}'}, body: new URLSearchParams({})}).then(r=>r.text()).then(html=>{ sel.innerHTML=html; }); }
});
function toggleStatus(id, checked){ fetch('{{ route('events.status') }}', {method:'POST', headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Content-Type':'application/json'}, body: JSON.stringify({id:id, status: checked})}).then(r=>r.json()).then(d=>{ /* toast */ }); }
function viewDetails(id){ fetch('{{ route('events.getDetails') }}', {method:'POST', headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Content-Type':'application/json'}, body: JSON.stringify({event_id:id})}).then(r=>r.text()).then(html=>{ document.getElementById('viewBody').innerHTML=html; document.getElementById('viewModal').classList.remove('hidden'); }); }
</script>@endpush
